local NativeCore = {x=26.84804,z=1.04297}
local NativeSpawn = {x=21.5,z=4.3}
local NativeBounds = {minX=-30.8,maxX=30.8,minZ=-30.8,maxZ=30.8}
function GetNativeOrigin()return NativeOrigin end
function GetBounds()return NativeBounds end
function GetSpawn()return NativeSpawn end
function GetCameraBounds()return {minX=1.2,maxX=62.8,minZ=2,maxZ=62,focusY=7.86,centreX=32,centreZ=34} end
function GroundY(x,z)
 local wx=math.max(0,math.min(63.999,x+NativeOrigin.x))*2
 local wz=math.max(0,math.min(63.999,z+NativeOrigin.z))*2
 local ix,iz=math.floor(wx),math.floor(wz);local tx,tz=wx-ix,wz-iz
 local a,b=NativeHeights[iz+1],NativeHeights[iz+2]
 return ((a[ix+1]*(1-tx)+a[ix+2]*tx)*(1-tz)+(b[ix+1]*(1-tx)+b[ix+2]*tx)*tz)-NativeOrigin.y
end
function TowerY(id)return NativeSlots[id] and NativeSlots[id].y or 0 end
function PointAt(r,d)
 d=math.max(0,math.min(r.length,d))
 for i=2,#r.points do local a,b=r.points[i-1],r.points[i]
  if d<=b.d then local t=(d-a.d)/math.max(.0001,b.d-a.d);return a.x+(b.x-a.x)*t,a.z+(b.z-a.z)*t,math.deg(math.atan(b.x-a.x,b.z-a.z)) end
 end
 local p=r.points[#r.points];return p.x,p.z,0
end
function Generate(theme,seed)
 local r={points={},length=0}
 for i,p in ipairs(NativePoints)do
  local q={x=p.x,z=p.z};if i>1 then local a=r.points[i-1];r.length=r.length+math.sqrt((q.x-a.x)^2+(q.z-a.z)^2)end
  q.d=r.length;r.points[i]=q
 end
 local slots={};for i,p in ipairs(NativeSlots)do local q={};for k,v in pairs(p)do q[k]=v end;slots[i]=q end
 return {theme="forest",seed=math.floor(seed or 1),version=3,template=1,nativeScene=true,anyTowerSlot=true,
  routes={r},slots=slots,core=NativeCore,spawn=NativeSpawn,bounds=NativeBounds,mapSize=64,hash="forest-authored-64-v4"}
end
function Validate(l)
 if not l or l.hash~="forest-authored-64-v4" or #l.slots~=11 or #l.routes~=1 then return false,"native-layout" end
 local r=l.routes[1];if r.length<50 or r.length>100 then return false,"native-route-length" end
 local p=r.points[#r.points];if math.abs(p.x-l.core.x)>.01 or math.abs(p.z-l.core.z)>.01 then return false,"core" end
 for i,s in ipairs(l.slots)do if s.id~=i or s.x<NativeBounds.minX or s.x>NativeBounds.maxX or s.z<NativeBounds.minZ or s.z>NativeBounds.maxZ then return false,"slot-bounds" end end
 return true
end
function Candidates(seed,C)
 local l=Generate("forest",seed)
 return {{id="forest",name="森林溪谷",seed=l.seed,description="64米森林 · 八处石坛 · 水晶防守",route=l.routes[1].points,layout=l}}
end
